// Start with a fresh output directory so preview drafts cannot survive a
// subsequent normal build. Preserve previous generated bytes for inspection.
const fs = require('node:fs');
const path = require('node:path');
const output = path.join(__dirname, '_site');
if (fs.existsSync(output)) {
  const history = path.join(__dirname, '_build-history');
  fs.mkdirSync(history, { recursive: true });
  fs.renameSync(output, path.join(history, new Date().toISOString().replace(/[:.]/g, '-') + '-' + process.pid));
}
